before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <atomic>
#include <iostream>
#include <thread>
int main() {
    std::atomic<int> count{0};
    auto work = [&] {
        for (int i = 0; i < 100; ++i) count.fetch_add(1);
    };
    {
        std::jthread first(work);
        std::jthread second(work);
    }
    int previous = count.fetch_add(3);
    std::cout << previous << " " << count.load() << "\n";
}
```

